targets.rawSql:
WITH latest AS (
  SELECT m.ingest_ts, m.value_num, m.device_id
  FROM admin_api.v_point_metric_effective m
  WHERE m.plant_id = ${plant_id:sqlstring}
    AND m.point_id = ${inlet_point_id:sqlstring}
    AND m.metric = ${metric_cards:sqlstring}
  ORDER BY m.ingest_ts DESC
  LIMIT 1
)
SELECT round(l.value_num::numeric, 3) AS value
FROM latest l
LEFT JOIN device d ON d.device_id = l.device_id
WHERE l.ingest_ts >= now() - ((2 * COALESCE(d.report_interval_sec, 60)) * interval '1 second');

