list.definition:
WITH metrics AS (
  SELECT count(DISTINCT v.metric) AS metric_count
  FROM admin_api.v_point_metric_effective v
  WHERE v.plant_id = ${plant_id:sqlstring}
    AND v.point_id IN (${inlet_point_id:sqlstring}, ${outlet_point_id:sqlstring})
)
SELECT gs::text AS __text,
       gs::text AS __value
FROM metrics,
     generate_series(1, GREATEST(1, ((metric_count + 4) / 5))) AS gs;

